import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";

// Định nghĩa style cho các phần tử
const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  z-index: 999;
  display: flex;
  justify-content: center;
  align-items: center;
  backdrop-filter: blur(5px); // Tạo hiệu ứng mờ cho giao diện chính
`;

const ConfirmBox = styled.div`
  background: white;
  padding: 30px;
  border-radius: 10px;
  text-align: center;
  width: 400px;
  position: relative; // Để đặt icon X vào vị trí chính xác
`;

const ConfirmText = styled.p`
  font-size: 18px;
  color: #333;
  margin-bottom: 25px;
`;

const ConfirmActions = styled.div`
  display: flex;
  justify-content: space-around;
`;

const ConfirmButton = styled.button`
  padding: 10px 20px;
  font-weight: bold;
  border: none;
  border-radius: 5px;
  cursor: pointer;
`;

const CloseIcon = styled.span`
  position: absolute;
  top: 10px;
  right: 10px;
  font-size: 20px;
  cursor: pointer;
  color: #333;
`;

const ConfirmDeleteUser = ({ onConfirm, onCancel, id }) => {
  const { t } = useTranslation();
  return (
    <Overlay>
      <ConfirmBox>
        <CloseIcon onClick={onCancel}>&times;</CloseIcon> {/* Icon X để đóng */}
        <ConfirmText>{t("ConfirmDeleteUserComponent.title")}</ConfirmText>
        <ConfirmActions>
          <ConfirmButton style={{ backgroundColor: "#007bff", color: "white" }} onClick={onConfirm}>
            {t("ConfirmDeleteUserComponent.confirm")}
          </ConfirmButton>
          <ConfirmButton style={{ backgroundColor: "#ddd" }} onClick={onCancel}>
            {t("ConfirmDeleteUserComponent.cancel")}
          </ConfirmButton>
        </ConfirmActions>
      </ConfirmBox>
    </Overlay>
  );
};

export default ConfirmDeleteUser;
